parameters.content:
{
  "id": "5cb7b28f-9ee8-4008-9dc1-055a1c759373",
  "version": "1.8",
  "name": "ExpenseApproval",
  "nodes": [
    {
      "id": "start",
      "type": "core.trigger.manual",
      "typeVersion": "1.0",
      "display": {
        "label": "Manual trigger"
      },
      "inputs": {
        "entryPointId": "ea4d1feb-046d-4990-b609-d5ba72a4388e",
        "isDefaultEntryPoint": true
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "Data passed when manually triggering the workflow.",
          "source": "null",
          "var": "output"
        }
      }
    },
    {
      "id": "prepareExpense",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Prepare Expense"
      },
      "inputs": {
        "script": "const name = ($vars.employeeName || \"\").trim();\nconst desc = ($vars.expenseDescription || \"\").trim();\nconst amt = $vars.amount || 0;\nconst receipt = ($vars.receiptUrl || \"\").trim();\nif (!name) { throw new Error(\"Employee name is required\"); }\nif (!desc) { throw new Error(\"Expense description is required\"); }\nif (amt <= 0) { throw new Error(\"Amount must be a positive number\"); }\nconst summary = name + \" submitted: \" + desc + \" for USD \" + amt;\nreturn { summary: summary };",
        "errorHandlingEnabled": true
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The return value of the script",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the script fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    {
      "id": "hitlManagerReview",
      "type": "uipath.human-in-the-loop.quick-form",
      "typeVersion": "1.0",
      "display": {
        "label": "Manager Review"
      },
      "inputs": {
        "schema": {
          "schemaId": "f2e8a1b3-c4d5-6789-abcd-ef0123456789",
          "fields": [
            {
              "id": "employeeName",
              "label": "Employee Name",
              "type": "text",
              "direction": "input",
              "binding": "vars.employeeName"
            },
            {
              "id": "expenseDescription",
              "label": "Description",
              "type": "text",
              "direction": "input",
              "binding": "vars.expenseDescription"
            },
            {
              "id": "amount",
              "label": "Amount (USD)",
              "type": "number",
              "direction": "input",
              "binding": "vars.amount"
            },
            {
              "id": "receiptUrl",
              "label": "Receipt URL",
              "type": "text",
              "direction": "input",
              "binding": "vars.receiptUrl"
            },
            {
              "id": "summary",
              "label": "Summary",
              "type": "text",
              "direction": "input",
              "binding": "vars.prepareExpense.output.summary"
            },
            {
              "id": "managerComments",
              "label": "Comments",
              "type": "text",
              "direction": "output",
              "variable": "vars.managerCommentsInput"
            }
          ],
          "outcomes": [
            {
              "id": "approve",
              "name": "Approve",
              "type": "string",
              "isPrimary": true,
              "action": "Continue"
            },
            {
              "id": "reject",
              "name": "Reject",
              "type": "string",
              "isPrimary": false,
              "action": "Continue"
            }
          ]
        },
        "recipient": {
          "channels": [
            "Email",
            "ActionCenter"
          ],
          "connections": {},
          "assignee": {
            "type": "group",
            "name": "expense-approvers"
          }
        },
        "priority": "Low"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "Task result data",
          "source": "=result",
          "var": "output",
          "properties": {
            "managerComments": {
              "type": "string"
            },
            "Action": {
              "type": "string",
              "enum": ["Approve", "Reject"],
              "default": "Approve"
            }
          }
        },
        "status": {
          "type": "string",
          "description": "Task completion status",
          "source": "=result.Action",
          "var": "status",
          "enum": ["Approve", "Reject"],
          "default": "Approve"
        }
      }
    },
    {
      "id": "checkManagerDecision",
      "type": "core.logic.decision",
      "typeVersion": "1.1",
      "display": {
        "label": "Manager Decision"
      },
      "inputs": {
        "expression": "$vars.hitlManagerReview.status === \"Approve\"",
        "trueLabel": "Approved",
        "falseLabel": "Rejected"
      }
    },
    {
      "id": "logApproved",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Log Approved"
      },
      "inputs": {
        "script": "return {\n  approvalStatus: \"Approved\",\n  managerComments: ($vars.hitlManagerReview.output.managerComments || \"\")\n};"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The return value of the script",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the script fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    {
      "id": "logRejected",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Log Rejected"
      },
      "inputs": {
        "script": "return {\n  approvalStatus: \"Rejected\",\n  managerComments: ($vars.hitlManagerReview.output.managerComments || \"\")\n};"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The return value of the script",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the script fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    {
      "id": "logError",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Log Error"
      },
      "inputs": {
        "script": "return { approvalStatus: \"Error\", managerComments: \"\" };"
